// TODO(wreck-it): add an assertion describing the correct behavior
test("WR-016: a11y: Elements must meet minimum color contrast ratio thresholds (color-contrast)", async ({ page, context }) => {
  const consoleErrors: string[] = [];
  const serverErrors: string[] = [];
  page.on("console", (m) => { if (m.type() === "error") consoleErrors.push(m.text()); });
  page.on("pageerror", (e) => consoleErrors.push(e.message));
  page.on("response", (r) => { if (r.status() >= 500) serverErrors.push(`${r.status()} ${r.url()}`); });
  let res: Awaited<ReturnType<typeof page.request.fetch>> | undefined;

  await page.goto("http://localhost:4318/products");
  await page.waitForLoadState("networkidle", { timeout: 5_000 }).catch(() => {});

  await page.locator('article').first().waitFor();
  const colors = await page.locator('article p').last().evaluate(el => ({fg:getComputedStyle(el).color, bg:getComputedStyle(el.closest('article')!).backgroundColor}));
  const luminance = (color: string) => { const rgb = color.match(/[\d.]+/g)!.slice(0,3).map(Number).map(x => x/255).map(x => x<=0.04045 ? x/12.92 : ((x+0.055)/1.055)**2.4); return 0.2126*rgb[0]+0.7152*rgb[1]+0.0722*rgb[2]; };
  const fg=luminance(colors.fg), bg=luminance(colors.bg);
  expect((Math.max(fg,bg)+0.05)/(Math.min(fg,bg)+0.05)).toBeGreaterThanOrEqual(4.5);
});
